# Dataclass with defaults, validation and derived fields
from dataclasses import dataclass, field, asdict, replace
from datetime import datetime, UTC
from enum import StrEnum

class UploadStatus(StrEnum):
    PROCESSING = "Processing"
    COMPLETED = "Completed"
    ERROR = "Error"

@dataclass(slots=True, kw_only=True)
class UploadJob:
    upload_id: int
    org_id: int
    report_type: str
    status: UploadStatus = UploadStatus.PROCESSING
    errors: list[str] = field(default_factory=list)     # safe mutable default
    created_at: datetime = field(default_factory=lambda: datetime.now(UTC))

    def __post_init__(self):
        if self.org_id <= 0:
            raise ValueError("org_id must be positive")

job = UploadJob(upload_id=1, org_id=7, report_type="amazon_orders")
done = replace(job, status=UploadStatus.COMPLETED)     # copy with change
print(asdict(done)["status"])                          # Completed
```

