# Frozen dataclass as a hashable value object / dict key
from dataclasses import dataclass

@dataclass(frozen=True, slots=True)
class ProductKey:
    id: int
    orgid: int

stock = {ProductKey(101, 7): 40}
print(stock[ProductKey(101, 7)])      # 40 - equal & same hash
# ProductKey(1, 2).id = 5  -> FrozenInstanceError
