# Composition + Protocol for testability
from typing import Protocol

class Writer(Protocol):
    def write_rows(self, table: str, rows: list[dict]) -> int: ...

class ReportProcessor:
    def __init__(self, writer: Writer):        # has-a, injected
        self.writer = writer

    @classmethod
    def with_defaults(cls) -> "ReportProcessor":
        return cls(writer=PrintWriter())

    def run(self, rows: list[dict]) -> int:
        clean = [r for r in rows if r.get("sku")]
        return self.writer.write_rows("inventory", clean)

class PrintWriter:                              # satisfies Writer structurally
    def write_rows(self, table, rows):
        print(f"{table}: {len(rows)} rows")
        return len(rows)

ReportProcessor.with_defaults().run([{"sku": "A"}, {"sku": None}])
```

